steps.body:
match goal with
| |- context [Z_to_bv ?width ?value] =>
    is_closed_term width;
    is_closed_term value;
    let literal := eval vm_compute in value in
    lazymatch literal with Z.neg _ => idtac end;
    let normalized := eval vm_compute in (bv_wrap width value) in
    let Hcast := fresh "Hclosed_cast" in
    assert (Hcast : Z_to_bv width value = Z_to_bv width normalized) by (
      apply bv_eq;
      rewrite !Z_to_bv_unsigned;
      reduce_closed (bv_wrap width value);
      reduce_closed (bv_wrap width normalized);
      reflexivity);
    rewrite Hcast
end.
repeat liStep.
